{
  "id": "ww-00035",
  "version": "0.1",
  "concept_id": "ww-00035",
  "identity": {
    "name": "Haven & Paw",
    "tagline": "Every animal deserves a safe place to land.",
    "one_line_description": "Haven & Paw is a civic-minded animal rescue shelter connecting abandoned and at-risk animals with loving homes through transparent operations, community campaigns, and trusted partnerships.",
    "domain": "nonprofit",
    "subdomain": "animal rescue shelter",
    "voice": [
      "earnest",
      "civic",
      "clear",
      "grounded",
      "trustworthy"
    ],
    "target_audience": "Local community members, prospective adopters, recurring donors, corporate partners, and civic-minded volunteers who believe in accountable, mission-driven animal welfare."
  },
  "pages": [
    {
      "slug": "home",
      "title": "Home",
      "role": "landing",
      "goal": "Establish Haven & Paw as the community's trusted animal rescue institution, orient first-time visitors to the mission and urgency, and guide them toward adoption, donation, or volunteering \u2014 anchored by an unmistakable civic arrival moment.",
      "meta_description": "Haven & Paw is your community's animal rescue shelter \u2014 rescuing, rehabilitating, and rehoming animals in need. Adopt, donate, or volunteer today.",
      "sections": [
        {
          "id": "home-section-1",
          "type": "hero",
          "intent": "Anchor the visitor with a strong civic arrival moment that communicates the shelter's purpose and urgency without melodrama \u2014 a steady, institutional confidence that says 'we are here, we are doing the work.'",
          "eyebrow": "Your Community Animal Shelter",
          "headline": "A Safe Place for Every Animal That Needs One",
          "subheadline": "Haven & Paw rescues, rehabilitates, and rehomes animals across the region. Open every day because animals need us every day.",
          "body": null,
          "items": [],
          "ctas": [
            {
              "label": "Meet Animals Available for Adoption",
              "target_page": "campaign"
            },
            {
              "label": "Support Our Work",
              "target_page": "donate"
            }
          ],
          "asset_ideas": []
        },
        {
          "id": "home-section-2",
          "type": "feature_grid",
          "intent": "Quickly orient visitors to the three pillars of the shelter's work \u2014 rescue, rehabilitation, and rehoming \u2014 so they understand the full scope of the mission before scrolling deeper.",
          "eyebrow": "What We Do",
          "headline": "Rescue. Rehabilitate. Rehome.",
          "subheadline": "Three commitments that guide every decision we make.",
          "body": null,
          "items": [
            {
              "title": "Emergency Rescue",
              "description": "We respond to calls for abandoned, injured, and at-risk animals 365 days a year, coordinating with local authorities and community members.",
              "metadata": {}
            },
            {
              "title": "Medical Rehabilitation",
              "description": "Every animal in our care receives veterinary assessment, treatment, and the time they need to recover before meeting their future family.",
              "metadata": {}
            },
            {
              "title": "Responsible Rehoming",
              "description": "Our adoption process matches animals with the right households \u2014 thorough, caring, and designed for lasting placements.",
              "metadata": {}
            }
          ],
          "ctas": [],
          "asset_ideas": []
        },
        {
          "id": "home-section-3",
          "type": "cta",
          "intent": "Close the home page with a confident civic call to action that invites the visitor to become part of the shelter's community \u2014 a single purposeful flourish that converts orientation into commitment.",
          "eyebrow": "Join the Community",
          "headline": "Animals Are Waiting. Your Help Makes the Difference.",
          "subheadline": "Adopt a companion, donate to our operations, or give your time as a volunteer. Every action matters.",
          "body": null,
          "items": [],
          "ctas": [
            {
              "label": "Adopt an Animal",
              "target_page": "campaign"
            },
            {
              "label": "Make a Donation",
              "target_page": "donate"
            },
            {
              "label": "View Our Partners",
              "target_page": "partners"
            }
          ],
          "asset_ideas": []
        }
      ]
    },
    {
      "slug": "campaign",
      "title": "Adoption Campaign",
      "role": "overview",
      "goal": "Present the shelter's current animals available for adoption in a clear, structured way that builds emotional connection and civic responsibility, and drives visitors toward completing an adoption inquiry.",
      "meta_description": "Browse animals currently available for adoption at Haven & Paw. Dogs, cats, and small animals waiting for their forever homes.",
      "sections": [
        {
          "id": "campaign-section-1",
          "type": "page_header",
          "intent": "Set the tone for the adoption experience \u2014 warm but grounded, institutional but human \u2014 so visitors feel they are entering a trusted, well-run process.",
          "eyebrow": "Current Adoption Campaign",
          "headline": "Find Your Next Family Member",
          "subheadline": "Every animal listed here has been rescued, assessed, and cleared for adoption. They are ready. Are you?",
