          "items": [],
          "ctas": [],
          "asset_ideas": []
        },
        {
          "id": "campaign-section-2",
          "type": "item_grid",
          "intent": "Showcase featured animals available for adoption with enough detail to spark genuine connection, letting the profiles do the storytelling with quiet confidence.",
          "eyebrow": "Animals Available Now",
          "headline": "Meet the Animals Looking for Homes",
          "subheadline": null,
          "body": null,
          "items": [
            {
              "title": "Biscuit \u2014 Labrador Mix, 3 years",
              "description": "Gentle, house-trained, and great with children. Biscuit was surrendered when his owner relocated and has been with us for six weeks.",
              "metadata": {
                "status": "Available",
                "size": "Large",
                "temperament": "Calm, affectionate"
