              "metadata": {
                "status": "Available",
                "size": "Small",
                "temperament": "Quiet, observant"
              }
            },
            {
              "title": "Theo \u2014 Beagle, 5 years",
              "description": "A loyal companion who loves routine walks and calm evenings. Theo was transferred from an overcrowded municipal shelter.",
              "metadata": {
                "status": "Available",
                "size": "Medium",
                "temperament": "Loyal, routine-oriented"
              }
            },
            {
              "title": "Clover \u2014 Rabbit, 1 year",
              "description": "Playful and social, Clover is ideal for families with older children or adults seeking a low-maintenance companion.",
              "metadata": {
                "status": "Available",
                "size": "Small",
                "temperament": "Playful, social"
              }
            }
          ],
          "ctas": [
            {
              "label": "Start an Adoption Inquiry",
              "target_page": "donate"
            }
          ],
          "asset_ideas": []
        },
        {
          "id": "campaign-section-3",
          "type": "story_block",
          "intent": "Build trust in the adoption process by walking prospective adopters through the steps clearly and institutionally \u2014 reducing anxiety and increasing follow-through.",
          "eyebrow": "How Adoption Works",
          "headline": "A Process Built Around Lasting Matches",
          "subheadline": "We take adoption seriously because the animals depend on it.",
          "body": "Our adoption process begins with a brief application form, followed by a meet-and-greet at the shelter. Our team reviews each application to ensure the match is right for both the animal and the household. Most adoptions are finalized within five to seven business days. We remain available for post-adoption support at no cost.",
          "items": [],
          "ctas": [
            {
              "label": "Download the Adoption Guide",
              "target_page": null
            }
          ],
          "asset_ideas": []
        }
      ]
    },
    {
      "slug": "data",
      "title": "Our Impact Data",
      "role": "editorial",
      "goal": "Demonstrate Haven & Paw's accountability and civic credibility through transparent operational data, reinforcing donor and partner confidence with numbers that feel alive and meaningful.",
      "meta_description": "Explore Haven & Paw's rescue and adoption statistics, operational transparency reports, and year-over-year impact data.",
      "sections": [
        {
          "id": "data-section-1",
          "type": "page_header",
          "intent": "Frame the data page as an act of institutional transparency \u2014 we share our numbers because we believe the community deserves to know exactly what their support achieves.",
          "eyebrow": "Transparency & Accountability",
          "headline": "The Numbers Behind Our Mission",
          "subheadline": "We publish our impact data because trust is built on evidence, not promises.",
          "body": null,
          "items": [],
          "ctas": [],
          "asset_ideas": []
