          "eyebrow": "How We Use Your Support",
          "headline": "Every Dollar Accounted For",
          "subheadline": "Our operating budget is community-funded and publicly reported.",
          "body": "Approximately 68% of all funds received go directly to animal care \u2014 veterinary services, food, housing, and behavioral support. 18% supports shelter operations and staffing. 14% is invested in outreach, adoption campaigns, and community education. We publish a full annual report each January and make it available to anyone who asks.",
          "items": [],
          "ctas": [
            {
              "label": "View Our Annual Report",
              "target_page": null
            },
            {
              "label": "Support the Mission",
              "target_page": "donate"
            }
          ],
          "asset_ideas": []
        }
      ]
