    {
      "slug": "partners",
      "title": "Partners & Community",
      "role": "overview",
      "goal": "Build institutional credibility by showcasing the network of civic organizations, veterinary partners, and corporate supporters that trust and sustain Haven & Paw, while inviting new partnerships.",
      "meta_description": "Meet the civic organizations, veterinary practices, and community businesses that partner with Haven & Paw to support animal rescue in our region.",
      "sections": [
        {
          "id": "partners-section-1",
          "type": "page_header",
          "intent": "Establish that Haven & Paw operates within a wider civic ecosystem \u2014 this is not a lone organization but a trusted node in a community-wide commitment to animal welfare.",
          "eyebrow": "Community & Partnerships",
          "headline": "We Don't Do This Alone",
